//! VEILOS `d3d11.dll` (and, forwarded to it, `dxgi.dll`): Direct3D 11 and
//! DXGI (WIN32_DESIGN.md G5f).
//!
//! Drawing goes to the kernel's rasterizer (src/raster3d.rs) as d3d9.dll's
//! does: vertex shaders run here, pixel shaders become the kernel's
//! programs and run on its raster workers.
//!
//!   com.rs     COM objects, aliases (one object, interfaces of both
//!              families), private data
//!   vtbl.rs    the vtables and IIDs (generated by gen_vtbl.py)
//!   dxgi.rs    factories, the adapter, its output, swap chains
//!   device.rs  ID3D11Device: creation, feature levels, format support
//!   res.rs     buffers, textures, views; Map, updates, copies, clears
//!   state.rs   blend, depth-stencil, rasterizer and sampler states,
//!              input layouts, queries
//!   context.rs ID3D11DeviceContext: the pipeline's bindings
//!   deferred.rs deferred contexts and command lists
//!   format.rs  DXGI formats
//!   dxbc.rs    shader bytecode (SM4/SM5) parsed
//!   compute.rs compute shaders: Dispatch on threads of this DLL
//!   shader.rs  shader objects
//!   vm.rs      the interpreter vertex shaders run on
//!   ps.rs      pixel shaders as the kernel's programs
//!   tess.rs    the tessellator (hull and domain shaders run in draw.rs)
//!   draw.rs    the input assembler, clipping, the viewport, the states as
//!              the kernel's, and the draw calls

#![no_std]
#![allow(non_snake_case, clippy::missing_safety_doc, clippy::too_many_arguments)]

