#[no_mangle]
pub extern "system" fn DllMain(_module: usize, _reason: u32, _reserved: usize) -> i32 {
    1
}

static DXGI_DEVICE_IIDS: [Guid; 3] = [IID_IDXGIOBJECT, IID_IDXGIDEVICE, IID_IDXGIDEVICE1];
static DXGI_RESOURCE_IIDS: [Guid; 3] = [IID_IDXGIOBJECT, IID_IDXGIDEVICESUBOBJECT, IID_IDXGIRESOURCE];
static DXGI_SURFACE_IIDS: [Guid; 4] = [IID_IDXGIOBJECT, IID_IDXGIDEVICESUBOBJECT, IID_IDXGISURFACE, IID_IDXGISURFACE1];

/// An alias of `main` for `iid` from the other family, if it has one.
pub fn alias_for(main: *mut Com, iid: &Guid) -> Option<*mut Com> {
    match body(main) {
        Body::Device(_) if DXGI_DEVICE_IIDS.contains(iid) => Some(alias(&IDXGIDEVICE1, &DXGI_DEVICE_IIDS)),
        Body::Resource(_) if DXGI_RESOURCE_IIDS[2] == *iid => Some(alias(&IDXGIRESOURCE, &DXGI_RESOURCE_IIDS)),
        Body::Resource(r) if r.dim == res::DIM_TEXTURE2D && DXGI_SURFACE_IIDS[2..].contains(iid) => Some(alias(&IDXGISURFACE1, &DXGI_SURFACE_IIDS)),
        _ => None,
    }
}

