#[no_mangle]
pub unsafe extern "system" fn D3D11CreateDevice(
    adapter: *mut Com,
    driver: u32,
    software: usize,
    flags: u32,
    levels: *const u32,
    nlevels: u32,
    sdk: u32,
    out: *mut *mut Com,
    level: *mut u32,
    ctx: *mut *mut Com,
) -> i32 {
    unsafe { device::create(adapter, driver, software, flags, levels, nlevels, sdk, out, level, ctx) }
}

#[no_mangle]
pub unsafe extern "system" fn D3D11CreateDeviceAndSwapChain(
    adapter: *mut Com,
    driver: u32,
    software: usize,
    flags: u32,
    levels: *const u32,
    nlevels: u32,
    sdk: u32,
    desc: *const dxgi::SwapChainDesc,
    swap: *mut *mut Com,
    out: *mut *mut Com,
    level: *mut u32,
    ctx: *mut *mut Com,
) -> i32 {
    let mut dev: *mut Com = core::ptr::null_mut();
    let r = unsafe { device::create(adapter, driver, software, flags, levels, nlevels, sdk, &mut dev, level, ctx) };
    if r < 0 {
        return r;
    }
    if !swap.is_null() {
        if desc.is_null() {
            unsafe { release(dev) };
            return E_INVALIDARG;
        }
        let r = unsafe { dxgi::swap_chain_for(dev, &*desc, swap) };
        if r < 0 {
            unsafe { release(dev) };
            return r;
        }
    }
    if out.is_null() {
        unsafe { release(dev) };
    } else {
        unsafe { *out = dev };
    }
    S_OK
}

